import { headers } from "next/headers";
import { notFound } from "next/navigation";
import { resolveTranslation } from "@/shared/resolve-translation";
import { findPostBySlug } from "../../posts-data";

interface PostPageProps {
	params: Promise<{ slug: string }>;
}

/**
 * The reader's accepted locales, most preferred first, parsed from the
 * request's `Accept-Language` header — the same preference order
 * {@link resolveTranslation} expects. A missing header resolves to an empty
 * list, which falls through resolution to the post's default locale.
 */
function acceptedLocales(acceptLanguage: string | null): string[] {
	if (!acceptLanguage) return [];

	return acceptLanguage
		.split(",")
		.map((entry) => entry.split(";")[0].trim())
		.filter((locale) => locale.length > 0);
}

/**
 * Post detail page. {@link resolveTranslation} turns the reader's accepted
 * locales plus the post's own translations into the one translation this page
 * renders.
 */
export default async function PostPage({ params }: PostPageProps) {
	const { slug } = await params;
	const post = findPostBySlug(slug);
	if (!post) notFound();

	const requestHeaders = await headers();
	const translation = resolveTranslation(
		post,
		acceptedLocales(requestHeaders.get("accept-language")),
	);
	if (!translation) notFound();

	return (
		<article>
			<h1>{translation.title}</h1>
			<p>{translation.body}</p>
		</article>
	);
}

import type { Post } from "@/shared/resolve-translation";

/**
 * The post catalog. It is checked in and compiled into the build. Reading it
 * from a content backend instead is a later change.
 */
export const POSTS: readonly Post[] = [
	{
		slug: "hello-world",
		defaultLocale: "ja-JP",
		translations: [
			{
				locale: "ja-JP",
				title: "はじめまして",
				body: "このブログについて書きました。",
			},
			{
				locale: "en-US",
				title: "Hello, world",
				body: "A short note about this blog.",
			},
		],
	},
	{
		slug: "on-writing-in-two-languages",
		defaultLocale: "ja-JP",
		translations: [
			{
				locale: "ja",
				title: "二言語で書くということ",
				body: "日本語と英語で書く理由について。",
			},
		],
	},
	{
		slug: "draft-notes",
		defaultLocale: "ja-JP",
		// A post that has not been translated into anything yet.
		translations: [],
	},
];

/** The post whose slug is `slug`, or `undefined` when the catalog has none. */
export function findPostBySlug(slug: string): Post | undefined {
	return POSTS.find((post) => post.slug === slug);
}

import { z } from "zod";

/** Upper bound on a post slug's length, enforced by the schema below. */
export const MAX_SLUG_LENGTH = 96;

/**
 * Shape of a post slug: lowercase alphanumeric groups joined by single
 * hyphens, with no leading, trailing, or doubled hyphen. A slug becomes part
 * of a URL path and a cache key, so it is validated before either is built
 * from it rather than trusted as-is.
 */
export const PostSlug = z
	.string()
	.min(1)
	.max(MAX_SLUG_LENGTH)
	.regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/);

export type PostSlug = z.infer<typeof PostSlug>;

/** Message shown next to a slug field that failed {@link PostSlug}. */
export const SLUG_VALIDATION_MESSAGE =
	"Use lowercase letters, numbers, and single hyphens (e.g. my-post-title).";

import type { Metadata } from "next";
import type { ReactNode } from "react";

export const metadata: Metadata = {
	title: {
		default: "tsuzuri",
		template: "%s · tsuzuri",
	},
	description: "A personal blog: portrait, bio, and posts.",
};

/**
 * Root layout for the `(site)` route group — the reader-facing pages. It is
 * the only route group so far: there is no admin console or API surface yet
 * to warrant a second one.
 */
export default function RootLayout({ children }: { children: ReactNode }) {
	return (
		<html lang="ja">
			<body>
				<header>
					<a href="/">tsuzuri</a>
				</header>
				<main>{children}</main>
			</body>
		</html>
	);
}

import { POSTS } from "./posts-data";

/** The home page: portrait, bio, and a list of posts linking to their detail page. */
export default function HomePage() {
	return (
		<>
			<section aria-label="profile">
				<h1>tsuzuri</h1>
				<p>A personal blog.</p>
			</section>
			<ul aria-label="posts">
				{POSTS.map((post) => (
					<li key={post.slug}>
						<a href={`/posts/${post.slug}`}>{post.slug}</a>
					</li>
				))}
			</ul>
		</>
	);
}

